#include <algorithm>
#include <functional>
#include <iostream>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, limit;
    in >> n >> limit;
    vector<int> citations(n);
    for (int i = 0; i < n; ++i) in >> citations[i];
    sort(citations.begin(), citations.end(), greater<int>());
    int h = 0;
    for (int i = 0; i < n; ++i)
        if (citations[i] >= i + 1) h = i + 1;
    int already = 0, oneAway = 0;
    for (int value : citations) {
        if (value >= h + 1) ++already;
        else if (value == h) ++oneAway;
    }
    if (h < n && already + min(oneAway, limit) >= h + 1) ++h;
    out << h << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
