#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int papers, n;
    in >> papers >> n;
    map<string, int> index;
    for (int i = 0; i < n; ++i) {
        string name;
        in >> name;
        index[name] = i;
    }
    vector<string> answer(n, string(n, '?'));
    for (int i = 0; i < n; ++i) answer[i][i] = 'B';
    for (int paper = 0; paper < papers; ++paper) {
        vector<string> names(n);
        vector<int> authors(n), group(n, 0);
        for (int i = 0; i < n; ++i) {
            in >> names[i];
            authors[i] = index.at(names[i]);
            if (i > 0)
                group[i] = group[i - 1] + (names[i - 1] > names[i]);
        }
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (group[i] != group[j]) {
                    answer[authors[i]][authors[j]] = '0';
                    answer[authors[j]][authors[i]] = '1';
                }
            }
        }
    }
    for (const string& row : answer) out << row << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
