#include <algorithm>
#include <iostream>
#include <set>
#include <string>
#include <utility>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n, m;
    in >> n >> m;
    vector<string> grid(n);
    for (int r = 0; r < n; ++r) in >> grid[r];
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};
    set<pair<int, int> > pairs;
    int flexible = 0;
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < m; ++c) {
            if (grid[r][c] != 'G') continue;
            int cows[4], count = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && grid[nr][nc] == 'C')
                    cows[count++] = nr * m + nc;
            }
            if (count >= 3) ++flexible;
            else if (count == 2) {
                if (cows[0] > cows[1]) swap(cows[0], cows[1]);
                pairs.insert(make_pair(cows[0], cows[1]));
            }
        }
    }
    out << flexible + static_cast<int>(pairs.size()) << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
